#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2; placed++){
        // Find where (placed+1) is
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element to position n-1 (last position)
        if(pos != n-1){
            // We want to move p[pos] to the end.
            // Use x = pos+1, y = n-1-pos. But x+y = pos+1+n-1-pos = n, need < n.
            // So use x = pos, y = n-1-pos if pos > 0
            // After: [suffix y=n-1-pos | middle(pos to pos) | prefix x=pos]
            // p[pos] is in the middle (single element), ends up at position n-1-pos
            // Actually let me think differently.
            // x=pos+1, y=n-1-pos: x+y=n not valid
            // x=pos, y=n-1-pos: x+y=n-1 < n (valid if pos>0 and n-1-pos>0 i.e. pos<n-1)
            if(pos > 0 && pos < n-1){
                int x = pos, y = n-1-pos;
                ops.push_back({x, y});
                apply(p, x, y);
                // p[pos] was at index pos. After: suffix [pos+1..n-1] (len y=n-1-pos) goes first,
                // middle [pos..pos] (len 1) stays, prefix [0..pos-1] goes last.
                // So p[pos] is now at index y = n-1-pos.
                pos = n-1-pos;
            }
            // If pos is still not n-1, do another op
            if(pos != n-1 && pos > 0){
                int x = pos, y = n-1-pos;
                if(x > 0 && y > 0 && x+y < n){
                    ops.push_back({x, y});
                    apply(p, x, y);
                    pos = n-1-pos;
                }
            }
        }
        // Step 2: Element at pos=n-1, move to position 'placed'
        // x=placed, y=1: after op, last element goes to pos 0, prefix goes to end
        // But we want it at position 'placed', so use y=1, x=placed (if placed>0)
        // Result: [p[n-1]] [p[placed]..p[n-2]] [p[0]..p[placed-1]] -> element at pos 0
        // Hmm, we need it at 'placed'. Use x=placed, y=1 if placed>0
        // After: [p[n-1], p[placed]..p[n-2], p[0]..p[placed-1]], element at 0, not placed.
        // Use y=n-placed-1, x=1: [p[placed+1..n-1], p[1..placed], p[0]]
        // Nope. Let me think: to get element from n-1 to placed:
        // x = placed+1, y = 1, need placed+2 < n, i.e. placed < n-2 (guaranteed by loop)
        // After: [p[n-1], p[placed+1..n-2], p[0..placed]]
        // Element at position 0, but we want position placed. Not right either.
        // Actually: suffix=p[n-1], middle=p[placed+1..n-2], prefix=p[0..placed]
        // Hmm wait - we already placed 1..placed, so p[0..placed-1] = 1..placed.
        // We want placed+1 at position placed. It's at n-1.
        // After x=placed+1,y=1: new = [p[n-1]] ++ [p[placed+1..n-2]] ++ [p[0..placed]]
        // p[n-1]=placed+1 goes to pos 0. p[0..placed]=[1..placed, something] goes to end.
        // This breaks already placed elements! 
        // Better: x=0 not allowed. Think again.
        // We need placed+1 (at n-1) to go to position placed.
        // After op(x,y): positions 0..y-1 = old suffix, y..n-1-x = old middle, n-x..n-1 = old prefix
        // Old suffix = p[n-y..n-1], old prefix = p[0..x-1], middle = p[x..n-y-1]
        // placed+1 is at p[n-1], in suffix if y>=1. It goes to position y-1 in new array.
        // We want y-1 = placed => y = placed+1.
        // Also need prefix p[0..x-1] = [1..placed, ...] to stay at front. They go to end! Bad.
        // Unless x = 0... but x>0 required.
        // So instead: first move already-placed prefix out of the way isn't feasible.
        // Alternative: just find element, set x=placed+1, y=n-1-pos, such that element ends at placed.
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;
        if(pos!=n-1){
            // General: use x=placed, y=n-pos if placed>0
            // y-1 + (pos - x) ... let me just brute force find good x,y
        }
        {
            int x=placed+1, y=1;
            if(x>0&&y>0&&x+y<n){
                ops.push_back({x,y});
                apply(p,x,y);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
